import numpy as np

def bisection_method(f, a, b, tol=1e-10, max_iter=100):
    if f(a) * f(b) >= 0:
        raise ValueError("f(a) and f(b) must have opposite signs")

    history = []

    for i in range(max_iter):
        c = (a + b) / 2
        history.append(c)

        if f(c) == 0 or (b - a) / 2 < tol:
            return c, history

        if f(a) * f(c) < 0:
            b = c
        else:
            a = c

    return (a + b) / 2, history

def estimate_iterations(a, b, tol):
    n = np.log2((b - a) / tol)
    return int(np.ceil(n))

def f(x):
    return x**3 - x - 2

root, history = bisection_method(f, 1.0, 2.0)
print(f"Root: {root:.10f}")
print(f"f(root): {f(root):.2e}")
print(f"Iterations: {len(history)}")
print(f"Estimated iterations: {estimate_iterations(1, 2, 1e-10)}")
